class Solution {
public:
    int countPermutations(int n) {
        if (n <= 1) return 1;
        long long MOD = 1000000007;
        long long ans = 1;
        for (int i = 1; i < n; ++i) {
            ans = (ans * i) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int countPermutations(int n) {
        if (n <= 1) return 1;
        long mod = 1000000007L;
        long ans = 1;
        for (int i = 1; i < n; i++) {
            ans = (ans * i) % mod;
        }
        return (int) ans;
    }
}

/**
 * @param {number} n
