var countPermutations = function(n) {
    if (n <= 1) return 1;
    const MOD = 1000000007n;
    let ans = 1n;
    for (let i = 1n; i < BigInt(n); i++) {
        ans = (ans * i) % MOD;
    }
    return Number(ans);
};
